<?php $publishedArticles=[];$articleCategories=[];$articleError='';try{$publishedArticles=rows('SELECT * FROM articles WHERE published_at IS NOT NULL AND published_at<=NOW() ORDER BY published_at DESC');$articleCategories=array_unique(array_column($publishedArticles,'category'));}catch(Throwable $ex){error_log($ex->getMessage());$articleError='Artikel belum dapat dimuat.';}$articleSearch=query('q');$articleCategory=query('category');$publishedArticles=array_filter($publishedArticles,fn($a)=>(!$articleSearch||mb_stripos($a['title'].' '.$a['excerpt'],$articleSearch)!==false)&&(!$articleCategory||$a['category']===$articleCategory)); ?>
<section class="public-page"><div class="page-heading"><p class="eyebrow">WAWASAN / ARTIKEL</p><h1>Pengetahuan untuk praktik industri.</h1><p>Artikel dan wawasan yang telah ditinjau untuk publikasi.</p></div><form class="filters" method="get"><label>Cari artikel<input name="q" type="search" value="<?= e($articleSearch) ?>"></label><label>Kategori<select name="category"><option value="">Semua kategori</option><?php foreach($articleCategories as $category): ?><option <?= $articleCategory===$category?'selected':'' ?>><?= e($category) ?></option><?php endforeach; ?></select></label><button class="btn" type="submit">Cari artikel</button><a class="btn secondary" href="insights.php">Reset</a></form><?php if(!$publishedArticles): ?><p class="notice info"><?= e($articleError?:'Belum ada artikel terbit yang sesuai. Topik usulan tersedia di bawah.') ?></p><?php endif; ?><div class="catalog-grid"><?php foreach($publishedArticles as $article): ?><article class="panel"><span class="badge"><?= e($article['category']) ?></span><h2 style="margin-top:16px"><?= e($article['title']) ?></h2><p class="muted"><?= e($article['excerpt']) ?></p><div class="actions"><a class="btn secondary" href="article.php?slug=<?= e($article['slug']) ?>">Baca artikel</a></div></article><?php endforeach; ?></div></section>
